package controlapi
import("net/http";"net/http/httptest";"os";"path/filepath";"strings";"testing";"open-mihomo-gateway/internal/mihomo")
func TestHostHostsSyncPreservesManualHostsAndReplacesManagedBlock(t *testing.T){store:=NewStore(t.TempDir());if err:=store.Ensure();err!=nil{t.Fatal(err)};hostFile:=filepath.Join(t.TempDir(),"hosts");if err:=os.WriteFile(hostFile,[]byte("192.0.2.10 nas.local\n0.0.0.0 ads.local\n"),0600);err!=nil{t.Fatal(err)};server:=&Server{store:store,configPath:filepath.Join(t.TempDir(),"missing.yaml")};_,doc,_,err:=server.loadProfileOverlay();if err!=nil{t.Fatal(err)};doc.DNS.Merge["hosts-file"]="1.1.1.1 manual.local";data,err:=mihomo.RenderProfileOverlay(doc);if err!=nil{t.Fatal(err)};if err:=store.SaveProfileOverlay(data);err!=nil{t.Fatal(err)};settings:=defaultHostHostsSyncSettings();settings.Enabled=true;settings.Path=hostFile;updated,err:=server.syncHostHosts(settings,true);if err!=nil{t.Fatal(err)};if updated.LastEntries!=2{t.Fatalf("entries=%d",updated.LastEntries)};raw,_,_,err:=server.loadProfileOverlay();if err!=nil{t.Fatal(err)};text:=string(raw);for _,want:=range []string{"manual.local","nas.local","ads.local",hostHostsBegin,hostHostsEnd}{if !strings.Contains(text,want){t.Fatalf("missing %q in %s",want,text)}};if err:=os.WriteFile(hostFile,[]byte("192.0.2.11 nas.local\n"),0600);err!=nil{t.Fatal(err)};updated,err=server.syncHostHosts(updated,true);if err!=nil{t.Fatal(err)};raw,_,_,_=server.loadProfileOverlay();text=string(raw);if strings.Contains(text,"ads.local"){t.Fatalf("stale managed host remained: %s",text)};if !strings.Contains(text,"manual.local")||!strings.Contains(text,"192.0.2.11"){t.Fatalf("manual or refreshed host missing: %s",text)}}
func TestHostHostsSyncAPIRejectsTooShortInterval(t *testing.T){store:=NewStore(t.TempDir());_ = store.Ensure();server:=&Server{store:store};r:=httptest.NewRequest(http.MethodPut,"/api/v1/host-hosts-sync",strings.NewReader(`{"interval_minutes":1}`));w:=httptest.NewRecorder();server.handleHostHostsSync(w,r);if w.Code!=http.StatusUnprocessableEntity{t.Fatalf("status=%d body=%s",w.Code,w.Body.String())}}

